items.solution_code:
def flexible_calculator(operator, *args):
    if operator == 'add':
        result = 0
        for num in args:
            result += num
        return result
    elif operator == 'subtract':
        result = args[0]
        for num in args[1:]:
            result -= num
        return result
    elif operator == 'multiply':
        result = 1
        for num in args:
            result *= num
        return result
    elif operator == 'divide':
        if not args:
            raise ValueError('At least one number required')
        result = args[0]
        for num in args[1:]:
            result /= num
        return result
    else:
        raise ValueError('Unsupported operator')

print(flexible_calculator('add', 1, 2, 3))      # 6
print(flexible_calculator('subtract', 10, 2, 1)) # 7

