def summarize(*data):
    total_numeric = 0
    total_length = 0
    for item in data:
        if isinstance(item, (int, float)) and not isinstance(item, bool):
            total_numeric += item
        elif isinstance(item, str):
            total_length += len(item)
    return {'total_numeric': total_numeric, 'total_string_length': total_length}

print(summarize(10, 'hello', 5.5, 'world'))
